-- Witness names are evidence types, not teacher portfolio sections.
-- Remove only blank autogenerated witness rows under their matching main element; preserve custom content or linked evidence.
DELETE FROM portfolio_sections
WHERE portfolio_sections.parent_id IS NOT NULL
  AND COALESCE(TRIM(portfolio_sections.body),'') = ''
  AND portfolio_sections.visibility='private'
  AND portfolio_sections.portfolio_id IN (SELECT p.id FROM portfolios p WHERE p.portfolio_type='teacher')
  AND NOT EXISTS (SELECT 1 FROM evidence e WHERE e.section_id=portfolio_sections.id)
  AND EXISTS (
    SELECT 1 FROM portfolio_sections AS main
    WHERE main.id=portfolio_sections.parent_id AND ((main.title='أداء الواجبات الوظيفية' AND portfolio_sections.title IN ('سجل الدوام الرسمي', 'سجل المناوبة والإشراف', 'سجل الانتظار', 'خطة توزيع المنهج')) OR
      (main.title='التفاعل مع المجتمع المحلي' AND portfolio_sections.title IN ('سجل مجتمعات التعلم', 'سجل تبادل الزيارات', 'تقرير درس تطبيقي', 'شهادات حضور')) OR
      (main.title='التفاعل مع أولياء الأمور' AND portfolio_sections.title IN ('صور من الجمعية العمومية', 'تقرير اجتماع مع ولي الأمر', 'نسخة من الخطة الأسبوعية')) OR
      (main.title='التنوع في استراتيجيات التدريس' AND portfolio_sections.title IN ('تقرير عن تطبيق استراتيجية', 'ملف إنجاز المعلم')) OR
      (main.title='تحسين نتائج المتعلمين' AND portfolio_sections.title IN ('نتائج الاختبارات القبلية والبعدية', 'كشف متابعة الطلاب')) OR
      (main.title='إعداد وتنفيذ خطة التعلم' AND portfolio_sections.title IN ('خطة توزيع المنهج', 'نماذج من إعداد الدروس', 'نماذج من الواجبات والاختبارات')) OR
      (main.title='توظيف تقنيات ووسائل التعلم المناسبة' AND portfolio_sections.title IN ('صور من الوسائل التعليمية', 'تقرير عن برنامج تقني')) OR
      (main.title='تهيئة البيئة التعليمية' AND portfolio_sections.title IN ('تقرير تصنيف الطلاب حسب أنماط التعلم', 'نماذج من التحفيز المادي والمعنوي')) OR
      (main.title='الإدارة الصفية' AND portfolio_sections.title IN ('كشف المتابعة', 'تطبيق إدارة الصف')) OR
      (main.title='تحليل نتائج المتعلمين وتشخيص مستوياتهم' AND portfolio_sections.title IN ('تقرير تحليل نتائج الطلاب', 'سجل معالجة الفاقد التعليمي')) OR
      (main.title='تنوع أساليب التقويم' AND portfolio_sections.title IN ('نماذج من الاختبارات', 'ملفات إنجاز الطلاب', 'نماذج من المهام الأدائية والمشاريع')))
  );
